        OPCODE_CLASS_XXLONG: begin
          unique casez (opcode[41 -: 10])
            10'b1111111100: operator_space_from_opcode = OPERATOR_SPACE_VECTOR;
            default: begin end
          endcase
        end
        default: begin end
      endcase
    end
